const $=id=>document.getElementById(id), DAY=86400000, KEY='sunpower-lead-demo-v2';
const people={sophie:{name:'Sophie Martin',role:'sales'},lucas:{name:'Lucas Bernard',role:'sales'},emma:{name:'Emma Dubois',role:'sales'},marc:{name:'Marc Laurent',role:'manager'}};
const names=['Thomas Petit','Camille Robert','Nicolas Moreau','Julie Laurent','Antoine Lefebvre','Léa Michel','Hugo Garcia','Chloé Roux'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function fresh(){const now=Date.UTC(2026,9,21,9);return{now,policy:{mode:'specified',user:'sophie',permission:'owner',recycle:true,pending:3,claimed:7,recycleRole:'sales'},leads:names.map((name,i)=>{const stage=['Pending Claim','Claimed','Qualified','Pending Claim','Claimed','Pending Claim','Qualified','Pending Claim'][i],owner=['sophie','lucas','emma','lucas','sophie',null,'emma',null][i],age=[2,4,1,1,6,2,3,1][i];return{id:'LD202610'+String(210033-i),name,email:name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(' ','.')+'@example.com',source:i%3?'Web':'Email',owner,stage,stageAt:now-age*DAY,assignedAt:now-age*DAY,history:[{title:owner?'Lead assigned':'Added to shared pool',detail:owner?'Assigned to '+people[owner].name+' · Initial assignment':'No owner · Available to all authorized users',at:now-age*DAY}]}})}}
let state;try{state=JSON.parse(localStorage.getItem(KEY))||fresh()}catch{state=fresh()}let tab='all',role='admin',lastFocus,toastTimer;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}render()}
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4000)}
function formatModal(){const root=$('modalContent');const form=root.querySelector('form');const header=document.createElement('header');header.className='modal-head';const body=document.createElement('div');body.className='modal-body';const footer=document.createElement('footer');footer.className='modal-foot';const buttons=root.querySelector('.buttonrow');if(buttons)footer.append(buttons);for(const child of [...root.children]){if(child===form)continue;if(child.tagName==='H2'||child.classList.contains('eyebrow'))header.append(child);else body.append(child)}if(form){for(const child of [...form.children])body.append(child);form.append(body,footer);root.replaceChildren(header,form)}else root.replaceChildren(header,body,footer)}
function open(id){if(id==='modalOverlay')formatModal();lastFocus=document.activeElement;$(id).classList.add('open');document.body.style.overflow='hidden';document.querySelector('main').inert=true;document.querySelector('nav').inert=true;document.querySelector('.demo').inert=true;setTimeout(()=>$(id).querySelector('button,input,select')?.focus(),50)}
function close(id){$(id).classList.remove('open');document.body.style.overflow='';document.querySelector('main').inert=false;document.querySelector('nav').inert=false;document.querySelector('.demo').inert=false;lastFocus?.focus()}
function date(t){return new Date(t).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'})}
function poolCandidates(r,exclude){return Object.keys(people).filter(k=>people[k].role===r&&k!==exclude)}
function pick(r,exclude){const p=poolCandidates(r,exclude);return p.length?p[Math.floor(Math.random()*p.length)]:null}
function canWork(l){return role==='admin'||!l.owner||l.owner==='sophie'}
function canReassign(l){return role==='admin'||(state.policy.permission==='owner'&&l.owner==='sophie')}
function log(l,title,detail){l.history.unshift({title,detail,at:state.now})}
function age(l){return Math.floor((state.now-l.stageAt)/DAY)}
function remaining(l){if(!state.policy.recycle||!l.owner||l.stage==='Qualified')return null;return state.policy[l.stage==='Claimed'?'claimed':'pending']-Math.floor((state.now-Math.max(l.stageAt,l.assignedAt))/DAY)}
function filtered(){const q=$('search').value.trim().toLowerCase();return state.leads.filter(l=>(tab==='all'||(tab==='mine'?l.owner==='sophie':!l.owner))&&($('stageFilter').value==='all'||l.stage===$('stageFilter').value)&&($('ownerFilter').value==='all'||(l.owner||'none')===$('ownerFilter').value)&&(!q||[l.name,l.email,l.id].some(s=>s.toLowerCase().includes(q))))}
function render(){const p=state.policy, ls=state.leads, pending=ls.filter(l=>l.stage==='Pending Claim').length,claimed=ls.filter(l=>l.stage==='Claimed').length,qualified=ls.filter(l=>l.stage==='Qualified').length;
$('stats').innerHTML=[['Total leads',ls.length,'In this partner workspace','▦'],['Pending claim',pending,'Awaiting a first response','◷'],['In progress',claimed,'Claimed by your team','↗'],['Qualified',qualified,'Ready for the next step','✓']].map(([label,n,sub,icon])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><div class="stat-bottom"><span class="number">${n.toString().padStart(2,'0')}</span><small>${sub}</small></div></div>`).join('');
$('policySummary').textContent=(p.mode==='specified'?'Assigned to '+(people[p.user]?.name||'selected user'):'Shared pool · No owner')+'  ·  '+(p.permission==='owner'?'Owner & admin can reassign':'Admin-only reassignment')+'  ·  '+(p.recycle?'Recycling on ('+p.pending+'d / '+p.claimed+'d)':'Recycling off');
$('allCount').textContent=ls.length;$('mineCount').textContent=ls.filter(l=>l.owner==='sophie').length;$('poolCount').textContent=ls.filter(l=>!l.owner).length;$('clockLabel').textContent='Demo date · '+date(state.now);$('settingsButton').disabled=role!=='admin';$('permissionNote').hidden=role==='admin';$('settingsButton').title=role==='admin'?'Configure lead assignment':'Only partner admins can change settings';$('policyEdit').textContent=role==='admin'?'View settings ↗':'Admin managed';$('policyEdit').disabled=role!=='admin';
for(const b of document.querySelectorAll('.tab')){b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-selected',b.dataset.tab===tab)}
const rows=filtered();$('empty').hidden=rows.length>0;$('resultCount').textContent=`Showing ${rows.length} of ${ls.length} leads`;
$('leads').innerHTML=rows.slice(0,10).map(l=>{const who=people[l.owner],rem=remaining(l),stageClass=l.stage==='Qualified'?'qualified':l.stage==='Claimed'?'claimed':'pending';let action=l.stage==='Pending Claim'&&l.owner?`<button data-action="accept" data-id="${l.id}" ${canWork(l)?'':'disabled'}>Accept</button>`:l.stage==='Claimed'?`<button data-action="qualify" data-id="${l.id}" ${canWork(l)?'':'disabled'}>Qualify</button>`:'';return `<tr><td><div class="name">${esc(l.name)}</div><span class="email">${esc(l.email)}</span></td><td><span class="leadno">${l.id}</span></td><td>Residential<div class="time">${l.source} · France</div></td><td>${who?`<div class="person"><span class="avatar">${who.name.split(' ').map(x=>x[0]).join('')}</span>${who.name}</div>`:'<span class="unassigned">— Unassigned</span><div class="time">Shared pool</div>'}</td><td><span class="pill ${stageClass}">${l.stage}</span></td><td>${age(l)} ${age(l)===1?'day':'days'}<div class="time ${rem!==null&&rem<=1?'overdue':''}">${rem!==null?(rem<=0?'Recycling due':`Recycles in ${rem}d`):l.stage==='Qualified'?'Recycling excluded':'Shared follow-up'}</div></td><td><div class="actions">${action}<button data-action="follow" data-id="${l.id}" ${canWork(l)?'':'disabled'}>Follow up</button><button data-action="reassign" data-id="${l.id}" ${canReassign(l)?'':'disabled'} title="${canReassign(l)?'Change lead owner':'Requires owner or admin permission'}">Reassign</button><button class="more" data-action="history" data-id="${l.id}" aria-label="History for ${esc(l.name)}">⋯</button></div></td></tr>`}).join('');}
function syncForm(){const p=state.policy;document.querySelector(`[name=mode][value=${p.mode}]`).checked=true;document.querySelector(`[name=permission][value=${p.permission}]`).checked=true;$('targetUser').value=p.user;$('recycleRole').value=p.recycleRole;$('recycle').checked=p.recycle;$('pendingDays').value=p.pending;$('claimedDays').value=p.claimed;syncFields()}
function syncFields(){$('userField').hidden=document.querySelector('[name=mode]:checked').value==='shared';$('recycleFields').hidden=!$('recycle').checked;for(const id of ['pendingDays','claimedDays','recycleRole'])$(id).disabled=!$('recycle').checked}
function settings(){if(role!=='admin')return;syncForm();open('settingsOverlay')}
$('settingsButton').onclick=settings;$('policyEdit').onclick=settings;
$('settingsForm').onchange=syncFields;$('settingsForm').onsubmit=e=>{e.preventDefault();if(role!=='admin')return;state.policy={mode:document.querySelector('[name=mode]:checked').value,user:$('targetUser').value,permission:document.querySelector('[name=permission]:checked').value,recycle:$('recycle').checked,pending:+$('pendingDays').value,claimed:+$('claimedDays').value,recycleRole:$('recycleRole').value};persist();close('settingsOverlay');toast('Assignment settings saved. Add a demo lead to try the policy.')};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>close(b.dataset.close));document.querySelectorAll('.overlay').forEach(el=>el.onclick=e=>{if(e.target===el)close(el.id)});document.addEventListener('keydown',e=>{const el=document.querySelector('.overlay.open');if(!el)return;if(e.key==='Escape')close(el.id);if(e.key==='Tab'){const nodes=[...el.querySelectorAll('button,input,select')].filter(x=>!x.disabled&&x.getClientRects().length);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
$('persona').onchange=e=>{role=e.target.value;render();toast(role==='admin'?'Previewing as Partner admin':'Previewing as Sophie Martin · Sales representative')};document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});['search','stageFilter','ownerFilter'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',render));
$('leads').onclick=e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const l=state.leads.find(x=>x.id===b.dataset.id);if(b.dataset.action==='history'){ $('historySubtitle').textContent=l.id+' · '+l.name;$('historyContent').innerHTML='<div class="timeline">'+l.history.map(h=>`<div class="event"><strong>${esc(h.title)}</strong><p>${esc(h.detail)}</p><small>${date(h.at)}</small></div>`).join('')+'</div>';open('historyOverlay');return}
if(b.dataset.action==='reassign'){if(!canReassign(l))return;const candidates=Object.keys(people).filter(k=>k!==l.owner);$('modalContent').innerHTML=`<div class="eyebrow">Change ownership</div><h2 id="modalTitle">Reassign lead</h2><p>${esc(l.name)} · ${l.id}</p><form id="reassignForm"><div class="field"><label>Current owner</label><div class="scope">${people[l.owner]?.name||'Shared pool · Unassigned'}</div></div><div class="field"><label for="newOwner">New owner</label><select id="newOwner">${candidates.map(k=>`<option value="${k}">${people[k].name} · ${people[k].role==='sales'?'Sales':'Manager'}</option>`).join('')}</select></div><div class="field"><label for="reason">Reason <span class="secondary">(required)</span></label><input type="text" id="reason" placeholder="e.g. Territory change or workload balancing" maxlength="240" required></div><div class="notice">The new owner will receive a notification. The recycling clock will restart.</div><div class="buttonrow"><button type="button" class="btn" id="cancelModal">Cancel</button><button type="submit" class="btn primary">Confirm reassignment</button></div></form>`;open('modalOverlay');$('cancelModal').onclick=()=>close('modalOverlay');$('reassignForm').onsubmit=ev=>{ev.preventDefault();const reason=$('reason').value.trim();if(!reason){$('reason').setCustomValidity('Enter a reason.');$('reason').reportValidity();return}const previous=people[l.owner]?.name||'Unassigned';l.owner=$('newOwner').value;l.assignedAt=state.now;log(l,'Lead reassigned',previous+' → '+people[l.owner].name+' · '+reason+' · By '+(role==='admin'?'Partner admin':'Sophie Martin'));persist();close('modalOverlay');toast('Lead reassigned. Notification recorded for '+people[l.owner].name+'.')};$('reason').oninput=()=>$('reason').setCustomValidity('');return}
if(!canWork(l))return;if(b.dataset.action==='accept'){l.stage='Claimed';l.stageAt=state.now;log(l,'Lead accepted','Owner '+people[l.owner].name+' accepted the lead.');persist();toast('Lead accepted and moved to Claimed.')}if(b.dataset.action==='qualify'){l.stage='Qualified';l.stageAt=state.now;log(l,'Lead qualified','Moved to Qualified by '+(role==='admin'?'Partner admin':'Sophie Martin')+'. Automatic recycling stopped.');persist();toast('Lead qualified. Automatic recycling no longer applies.')}
if(b.dataset.action==='follow'){$('modalContent').innerHTML=`<div class="eyebrow">Lead activity</div><h2 id="modalTitle">Record follow-up</h2><p>${esc(l.name)} · ${l.id}</p><form id="followForm"><div class="field"><label for="followNote">Follow-up note</label><input type="text" id="followNote" maxlength="300" placeholder="e.g. Called customer; site visit requested" required></div><div class="notice">${l.owner?'A follow-up note does not reset the stage timer.':'This is a shared lead. Recording a note keeps it unassigned and available to all authorized users.'}</div><div class="buttonrow"><button type="button" class="btn" id="cancelModal">Cancel</button><button type="submit" class="btn primary">Save follow-up</button></div></form>`;open('modalOverlay');$('cancelModal').onclick=()=>close('modalOverlay');$('followForm').onsubmit=ev=>{ev.preventDefault();const note=$('followNote').value.trim();if(!note)return;log(l,'Follow-up recorded',note+' · By '+(role==='admin'?'Partner admin':'Sophie Martin'));persist();close('modalOverlay');toast('Follow-up saved'+(!l.owner?'. This lead remains in the shared pool.':'.'))}}};
$('advance').onclick=()=>{state.now+=DAY;let recycled=0,blocked=0;for(const l of state.leads){const rem=remaining(l);if(rem===null||rem>0)continue;const next=pick(state.policy.recycleRole,l.owner);if(next){const old=people[l.owner].name;l.owner=next;l.assignedAt=state.now;log(l,'Automatically reassigned',old+' → '+people[next].name+' · Stage time limit reached · New owner notified');recycled++}else{blocked++;log(l,'Admin alert · No eligible alternative','Ownership retained. No other active user in the configured role.')}}persist();toast(`Advanced to ${date(state.now)} · ${recycled} lead${recycled===1?'':'s'} recycled${blocked?' · '+blocked+' admin alert(s)':''}.`)};
$('newLead').onclick=()=>{if(state.leads.length>=10){toast('Demo limited to 10 leads. Reset the demo to start again.');return}const n=state.leads.length-8,owner=state.policy.mode==='specified'?state.policy.user:null;const l={id:'LD202610'+(210050+n),name:['Alice Dupont','Louis Mercier'][n],email:['alice.dupont','louis.mercier'][n]+'@example.com',source:'Web',owner,stage:'Pending Claim',stageAt:state.now,assignedAt:state.now,history:[]};log(l,owner?'Lead assigned':'Added to shared pool',owner?'Assigned to selected user → '+people[owner].name+' · New lead notification recorded':'No owner · All authorized users may follow up');state.leads.unshift(l);persist();toast(owner?'New lead assigned to '+people[owner].name+'.':'New lead added to shared pool. All authorized users may follow up.')};
$('reset').onclick=()=>{$('modalContent').innerHTML='<h2 id="modalTitle">Reset demo?</h2><p>This will restore the sample leads, assignment policy and demo clock.</p><div class="buttonrow"><button class="btn" id="cancelModal">Cancel</button><button class="btn primary" id="confirmReset">Reset demo</button></div>';open('modalOverlay');$('cancelModal').onclick=()=>close('modalOverlay');$('confirmReset').onclick=()=>{state=fresh();tab='all';$('search').value='';$('stageFilter').value='all';$('ownerFilter').value='all';role='admin';$('persona').value='admin';persist();close('modalOverlay');toast('Demo reset to its original state.')}};
$('export').onclick=()=>{const rows=[['Lead No.','Contact','Email','Owner','Stage','Days in stage'],...filtered().map(l=>[l.id,l.name,l.email,people[l.owner]?.name||'Unassigned',l.stage,age(l)])];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='sunpower-demo-leads.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Filtered leads exported as CSV.')};render();

function resetFilters(){$('search').value='';$('stageFilter').value='all';$('ownerFilter').value='all';render()}
$('resetFilters').onclick=resetFilters;$('emptyReset').onclick=resetFilters;$('searchButton').onclick=render;
